#nullable enable // autogenerated

using MVZ2.GameContent.Contraptions;
using MVZ2.GameContent.Stages;
using MVZ2.Vanilla.Audios;

using MVZ2Logic.Blueprints;
using MVZ2Logic.Definitions;
using MVZ2Logic.Entities;

using PVZEngine.Entities;
using PVZEngine.Level;
using PVZEngine.SeedPacks;

namespace MVZ2.GameContent.Seeds
{
    // 更换器械：子弹数量与射速都升满后，可把矿车上的活塞发射器更换为融合体 EXPANDispenser_Pistenser。
    // 更换后骑手被摧毁时重新召唤的也是融合体（见 ShootBalloonStageBehaviour.ReplaceRider）。
    // 射速等级会被继承，子弹数量等级不继承（融合体本身弹数就多）。
    [AutoSeedOptionDefinition(VanillaBlueprintNames.HeavyWeaponContraptionSwap)]
    public class HeavyWeaponContraptionSwap : SeedOptionDefinition
    {
        public HeavyWeaponContraptionSwap(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Update(SeedPack seedPack, float rechargeSpeed)
        {
            base.Update(seedPack, rechargeSpeed);
            seedPack.SetProperty(EngineSeedProps.DISABLE_ID, IsValid(seedPack.Level) ? null : LogicBlueprintErrors.invalid);
        }
        public override void Use(SeedPack seedPack)
        {
            base.Use(seedPack);
            Use(seedPack.Level);
        }
        public override void Use(LevelEngine level, SeedDefinition seedDef)
        {
            base.Use(level, seedDef);
            Use(level);
        }
        private void Use(LevelEngine level)
        {
            if (!IsValid(level))
                return;
            ShootBalloonStageBehaviour.ReplaceRider(level);
        }
        private static bool IsValid(LevelEngine level)
        {
            // 条件：当前骑手是活塞发射器，且子弹数量与射速都已满级
            var rider = HeavyWeaponBlueprintUtils.FindRider(level);
            if (rider == null)
                return false;
            if (!rider.IsEntityOf(VanillaContraptionID.pistenser))
                return false;
            if (Pistenser.CanUpgradeBulletCount(rider))
                return false;
            if (HeavyWeaponUpgradeUtils.CanUpgradeRapid(rider))
                return false;
            return true;
        }
    }
}
